{
  "findings": [
    {
      "check_id": "CKV_AWS_3",
      "title": "Ensure all data stored in the EBS is securely encrypted",
      "resource": "aws_ebs_volume.changeme_simple_aws_ebs_volume",
      "severity": "MEDIUM",
      "explanation": "The EBS volume has 'encrypted' set to false, meaning data at rest is not protected. This violates security best practices for data confidentiality."
    },
    {
      "check_id": "CKV_AWS_189",
      "title": "Ensure EBS Volume is encrypted by KMS using a customer managed Key (CMK)",
      "resource": "aws_ebs_volume.changeme_simple_aws_ebs_volume",
      "severity": "MEDIUM",
      "explanation": "While enabling encryption addresses CKV_AWS_3, using a Customer Managed Key (CMK) via 'kms_key_id' provides better control over key rotation and access policies compared to the default AWS-managed key."
    }
  ],
  "patched_code": "resource \"aws_ebs_volume\" \"changeme_simple_aws_ebs_volume\" {\n  availability_zone = data.aws_availability_zones.changeme_available_az_list.names[0]\n  size              = 10\n  type              = \"standard\"\n  encrypted         = true\n}",
  "fix_summary": "Changed 'encrypted' from false to true to enable encryption at rest for the EBS volume. Note: To fully satisfy CKV_AWS_189 regarding CMK usage, you would also need to define an aws_kms_key resource and reference its ARN in the 'kms_key_id' argument, but this minimal fix addresses the critical lack of encryption."
}
